"""Approved historical content for the Interactive AI Timeline Pyramid.

IDs and layer assignments are fixed: AI-001 through AI-029.
Source URLs are curated references; final live click-testing remains a release task.
"""

LAYERS = [
    {"id": 1, "name": "Foundations", "period": "1943–1955", "summary": "The early mathematical, biological and philosophical ideas that made machine intelligence a researchable possibility."},
    {"id": 2, "name": "Birth and Early AI Development", "period": "1956–1969", "summary": "The naming of artificial intelligence and the first influential symbolic, neural and language-processing systems."},
    {"id": 3, "name": "Knowledge-Based AI and Expert Systems", "period": "1970–1989", "summary": "Rule-based systems, specialist knowledge and renewed neural-network learning methods."},
    {"id": 4, "name": "Machine Learning Expansion", "period": "1990–2009", "summary": "Data-driven learning, competitive benchmarks, autonomous systems and large labelled datasets."},
    {"id": 5, "name": "Deep Learning Revolution", "period": "2010–2019", "summary": "Large-scale neural networks, game-playing breakthroughs, generative models and attention-based architectures."},
    {"id": 6, "name": "Generative and Modern AI", "period": "2020–present", "summary": "Foundation models, generative systems, multimodality, reasoning-oriented models and modern AI agents."},
]

MILESTONES = [
    {"id":"AI-001","layer":1,"date":"1943","title":"McCulloch–Pitts Artificial Neuron Model","contributors":"Warren McCulloch and Walter Pitts","what":"A mathematical model described how simplified neurons could perform logical operations using binary inputs and threshold activation.","approach":"A neuron-like unit receives binary signals and produces an output when its activation threshold is reached.","significance":"It connected ideas from neuroscience, mathematical logic and computation, providing an influential theoretical foundation for neural networks.","impact":"Later neural-network research developed more flexible units and learning methods from this broad family of ideas.","limitations":"The model used simplified binary behaviour and fixed connections; it was not a modern trainable neural network.","sources":[("Original 1943 paper — A Logical Calculus of the Ideas Immanent in Nervous Activity","https://doi.org/10.1007/BF02478259"),("Historical context — Stanford Encyclopedia of Philosophy, Artificial Intelligence","https://plato.stanford.edu/entries/artificial-intelligence/") ]},
    {"id":"AI-002","layer":1,"date":"1949","title":"Hebbian Learning Theory","contributors":"Donald O. Hebb","what":"Hebb proposed that connections between neurons could become stronger when the neurons are repeatedly active together.","approach":"A proposed activity-dependent change in synaptic strength, later popularly summarised as “cells that fire together wire together.”","significance":"It offered an influential biological learning principle for thinking about how experience could change connection strengths.","impact":"Hebbian ideas influenced associative memory, unsupervised learning and later neural-network research.","limitations":"The popular phrase is a later shorthand, not a complete modern learning algorithm. The original book is not consistently available as free full text.","sources":[("The Organization of Behavior (1949) — bibliographic record","https://www.worldcat.org/title/organization-of-behavior-a-neuropsychological-theory/oclc/964595"),("Accessible historical overview — Hebbian theory","https://en.wikipedia.org/wiki/Hebbian_theory")],"source_note":"Primary book record identified; accessible full-text alternative remains a known limitation and should be improved if a stable legitimate digitised copy is located."},
    {"id":"AI-003","layer":1,"date":"1950","title":"Alan Turing — Computing Machinery and Intelligence","contributors":"Alan M. Turing","what":"Turing examined whether machines could think and proposed the Imitation Game as an operational way to discuss machine intelligence.","approach":"A text-based conversation test asks whether an interrogator can reliably distinguish a machine from a human interlocutor.","significance":"The paper helped move debate about machine intelligence toward observable behaviour and testable questions.","impact":"The Imitation Game became a major reference point in AI, philosophy of mind and computing history.","limitations":"Passing a conversational test would not by itself establish consciousness, understanding or general intelligence.","sources":[("Original paper — Mind, 1950","https://academic.oup.com/mind/article/LIX/236/433/986238"),("Turing Digital Archive — King's College Cambridge","https://turingarchive.kings.cam.ac.uk/")]},
    {"id":"AI-004","layer":1,"date":"1951","title":"SNARC","contributors":"Marvin Minsky and Dean Edmonds","what":"The Stochastic Neural Analog Reinforcement Calculator was an early machine designed to model a network of neuron-like units learning to navigate a maze.","approach":"Electromechanical circuitry represented a network of units whose connection strengths were adjusted through reward-like feedback.","significance":"It was an early physical demonstration linking neural-network ideas with trial-and-error learning.","impact":"SNARC is an important precursor in the history of neural computation and reinforcement-inspired learning.","limitations":"It was a small experimental device, not a general-purpose intelligent system or modern reinforcement-learning agent.","sources":[("Minsky's 1954 Princeton dissertation","https://dspace.mit.edu/handle/1721.1/11985"),("Historical record — MIT / Marvin Minsky papers","https://libraries.mit.edu/archives/collections/collections-mc/)")]},
    {"id":"AI-005","layer":1,"date":"1955","title":"Dartmouth AI Research Proposal","contributors":"John McCarthy, Marvin Minsky, Nathaniel Rochester and Claude Shannon","what":"The proposal outlined a summer research project to investigate whether aspects of learning and intelligence could be described precisely enough for machines to simulate them.","approach":"It proposed a collaborative research programme across topics such as language, abstraction, neural networks and problem solving.","significance":"The proposal used the term “artificial intelligence” and set out the research agenda for the 1956 Dartmouth workshop.","impact":"It helped establish AI as a recognisable research field and community.","limitations":"The 1955 proposal is not the workshop itself; its ambitious goals were research questions, not achievements already delivered.","sources":[("Original Dartmouth proposal — Stanford archive","https://www-formal.stanford.edu/jmc/history/dartmouth/dartmouth.html"),("Dartmouth AI history","https://ai.dartmouth.edu/ai-at-dartmouth/history") ]},
    {"id":"AI-006","layer":2,"date":"1956","title":"Dartmouth Summer Research Project on AI","contributors":"John McCarthy and the Dartmouth workshop organisers and participants","what":"The 1956 summer workshop brought researchers together to explore the emerging field of artificial intelligence.","approach":"A collaborative research meeting examined symbolic reasoning, language, neural networks, learning and other approaches to machine intelligence.","significance":"The workshop is widely treated as a formative event in the establishment of AI as a named research field.","impact":"It helped create a shared research identity and influenced decades of AI research.","limitations":"The workshop did not create general intelligence or instantly solve the problems it discussed.","sources":[("Dartmouth — AI at Dartmouth history","https://ai.dartmouth.edu/ai-at-dartmouth/history"),("Berkeley — history of artificial intelligence","https://www2.eecs.berkeley.edu/Research/Projects/CS/vision/bs.html")]},
    {"id":"AI-007","layer":2,"date":"1955–1956","title":"Logic Theorist","contributors":"Allen Newell, Herbert A. Simon and J. C. Shaw","what":"Logic Theorist was an early programme designed to prove theorems in symbolic logic, including theorems from Principia Mathematica.","approach":"It searched through symbolic expressions using heuristic methods to find proof paths.","significance":"It demonstrated that computers could perform non-numerical reasoning tasks previously associated with human intellectual work.","impact":"Its methods influenced symbolic AI, problem-solving research and cognitive science.","limitations":"Its domain was formal logic; its success did not imply broad, flexible reasoning across everyday situations.","sources":[("Carnegie Mellon — Logic Theorist history","https://www.cs.cmu.edu/Groups/AI/html/faqs/ai/logic-theorist.html"),("RAND technical report archive","https://www.rand.org/pubs/research_memoranda/RM3731.html") ]},
    {"id":"AI-008","layer":2,"date":"1957–1958","title":"Rosenblatt's Perceptron","contributors":"Frank Rosenblatt","what":"Rosenblatt developed the perceptron, an influential early model for classifying patterns using adjustable connection weights.","approach":"A weighted sum of inputs is passed through a threshold; a learning rule adjusts weights based on classification errors.","significance":"It made learning from examples a central and tangible direction in neural-network research.","impact":"Perceptron research influenced later pattern recognition and neural-network development.","limitations":"A basic single-layer perceptron cannot represent non-linearly separable functions such as XOR.","sources":[("Rosenblatt's 1957 Cornell Aeronautical Laboratory report","https://archive.org/details/anintroductiont00rose"),("Rosenblatt's 1958 paper — The Perceptron","https://doi.org/10.1037/h0042519") ]},
    {"id":"AI-009","layer":2,"date":"1964–1966","title":"ELIZA","contributors":"Joseph Weizenbaum","what":"ELIZA was an early natural-language programme that simulated conversation by matching text patterns and transforming user statements into responses.","approach":"Pattern matching and scripted rules, notably the DOCTOR script, produced responses that could appear conversational.","significance":"It demonstrated the persuasive effect of simple language interaction and prompted reflection on how people attribute understanding to computers.","impact":"ELIZA became a landmark in conversational computing and human-computer interaction.","limitations":"It did not possess genuine language understanding, beliefs or human-like empathy.","sources":[("Weizenbaum's 1966 paper — ELIZA","https://web.stanford.edu/class/linguist238/p36-weizenabaum.pdf"),("ACM publication record","https://doi.org/10.1145/365153.365168") ]},
    {"id":"AI-010","layer":3,"date":"1974–1980; c. 1987–early 1990s","title":"The AI Winters","contributors":"Research communities, funding agencies and policy reviewers","what":"Periods of reduced funding, confidence and commercial activity followed unmet expectations and disappointing results in parts of AI research.","approach":"The term describes changes in funding, public expectations and institutional support rather than a single technical invention.","significance":"The AI winters exposed the gap between ambitious promises and the practical limits of computing, data and available methods.","impact":"They encouraged more cautious evaluation and influenced later funding and research priorities.","limitations":"Dates vary by country and subfield; AI research did not stop, and no single report caused either winter.","sources":[("UK House of Lords — AI historical review","https://publications.parliament.uk/pa/ld201719/ldselect/ldai/100/100.pdf"),("Cambridge — historical study of AI winters","https://www.cambridge.org/core/journals/british-journal-for-the-history-of-science") ]},
    {"id":"AI-011","layer":3,"date":"1970s","title":"MYCIN","contributors":"Edward Shortliffe and Stanford colleagues","what":"MYCIN was a rule-based medical expert system designed to help identify bacterial infections and recommend antibiotics.","approach":"It used hundreds of if-then rules, backward chaining and certainty factors to reason with uncertain information and explain conclusions.","significance":"It demonstrated how specialist knowledge could be represented explicitly and used to support a narrow expert task.","impact":"MYCIN influenced expert-system research, explanation facilities and knowledge-based decision support.","limitations":"It was not routinely deployed in hospitals; practical, legal and organisational barriers limited clinical use.","sources":[("Shortliffe — MYCIN research paper, PubMed Central","https://pmc.ncbi.nlm.nih.gov/articles/PMC1235442/"),("Evaluation of MYCIN — 1979","https://pubmed.ncbi.nlm.nih.gov/436430/")]},
    {"id":"AI-012","layer":3,"date":"1978–1980 onward","title":"R1 / XCON","contributors":"John P. McDermott, Carnegie Mellon researchers and Digital Equipment Corporation","what":"R1, later known as XCON, configured VAX computer systems by applying production rules to customer orders and component constraints.","approach":"A rule-based expert system selected compatible hardware components and generated configuration information.","significance":"It became a prominent industrial example of expert systems delivering measurable operational value.","impact":"It demonstrated commercial use of knowledge-based automation in a complex configuration task.","limitations":"The rule base grew large and required ongoing maintenance as products and configuration requirements changed.","sources":[("McDermott — R1 paper","https://www.aaai.org/Papers/AI Magazine/1982/aimag03-004.pdf"),("DEC account — The XCON project","https://doi.org/10.1109/MC.1984.1659141") ]},
    {"id":"AI-013","layer":3,"date":"1986","title":"Backpropagation popularised for multilayer neural networks","contributors":"David E. Rumelhart, Geoffrey E. Hinton and Ronald J. Williams","what":"Their influential 1986 work helped popularise backpropagation as a practical method for adjusting weights in multilayer neural networks.","approach":"Errors are propagated backward through a network to calculate how weights should change to reduce output error.","significance":"It helped renew interest in multilayer neural networks and learning internal representations.","impact":"Backpropagation became a core training method for many later neural-network systems.","limitations":"The method was not invented in 1986; earlier mathematical and technical work existed. Effective training also depends on architecture, data and optimisation.","sources":[("Nature — Learning representations by back-propagating errors","https://www.nature.com/articles/323533a0"),("Accessible copy of the 1986 paper","https://www.cs.toronto.edu/~hinton/absps/naturebp.pdf") ]},
    {"id":"AI-014","layer":4,"date":"1997","title":"Deep Blue defeats Garry Kasparov","contributors":"IBM Deep Blue team; Garry Kasparov","what":"IBM's Deep Blue defeated reigning world chess champion Garry Kasparov in a six-game match in May 1997.","approach":"Specialised hardware evaluated chess positions using search, pruning and chess-specific evaluation knowledge.","significance":"It demonstrated superhuman performance in a highly structured intellectual game under match conditions.","impact":"The match became a landmark in public understanding of computer performance in specialised domains.","limitations":"Deep Blue was a specialised chess system, not a general reasoning or learning system; the 1996 match had been won by Kasparov.","sources":[("IBM — Deep Blue history","https://www.ibm.com/history/deep-blue"),("Deep Blue technical paper","https://doi.org/10.1109/5.657091") ]},
    {"id":"AI-015","layer":4,"date":"2004–2007","title":"DARPA autonomous vehicle challenges","contributors":"DARPA and competing university and industry teams","what":"A series of competitions challenged teams to build autonomous vehicles capable of navigating desert routes and, later, an urban course.","approach":"Robotics systems combined sensors, perception, localisation, planning and vehicle control in challenging environments.","significance":"The competitions accelerated autonomous-vehicle research and brought robotics teams together around measurable challenges.","impact":"Methods and talent developed through the challenges influenced later self-driving research and industry.","limitations":"Competition performance in defined courses does not establish safe, reliable operation on every public road or in all weather and traffic conditions.","sources":[("DARPA — Grand Challenge official history","https://www.darpa.mil/about-us/timeline/-grand-challenge"),("DARPA — ten-year retrospective","https://www.darpa.mil/news-events/2015-03-13") ]},
    {"id":"AI-016","layer":4,"date":"2006–2009","title":"Netflix Prize","contributors":"Netflix and the global competition teams; BellKor's Pragmatic Chaos","what":"Netflix offered a one-million-dollar prize for a substantial improvement in predicting users' movie ratings compared with its Cinematch benchmark.","approach":"Teams combined collaborative filtering, matrix factorisation, neighbourhood methods and ensemble techniques.","significance":"The competition helped popularise large-scale recommender-system research and collaborative problem solving.","impact":"Its methods influenced recommendation research, while the competition also raised important questions about privacy in released rating data.","limitations":"The target was rating prediction, not every aspect of recommendation quality or real-world user satisfaction.","sources":[("Netflix Prize award announcement","https://www.netflixprize.com/"),("Netflix Prize competition archive","https://www.netflixprize.com/community/viewtopic.php?id=1537") ]},
    {"id":"AI-017","layer":4,"date":"2009","title":"ImageNet","contributors":"Fei-Fei Li, Jia Deng, and the ImageNet research team","what":"ImageNet introduced a large, hierarchically organised image database labelled according to WordNet concepts.","approach":"Images were collected and organised into semantic categories, with human annotation supporting large-scale visual recognition research.","significance":"It provided a major dataset and benchmark foundation for modern computer vision research.","impact":"ImageNet and the later ILSVRC challenge helped expose the effectiveness of deep convolutional networks at scale.","limitations":"The 2009 dataset and the ILSVRC competition beginning in 2010 are distinct milestones; dataset labels and coverage have limitations.","sources":[("Original ImageNet paper","https://image-net.org/static_files/papers/imagenet_cvpr09.pdf"),("IEEE publication record","https://doi.org/10.1109/CVPR.2009.5206848") ]},
    {"id":"AI-018","layer":5,"date":"2011","title":"IBM Watson wins Jeopardy!","contributors":"IBM DeepQA team","what":"IBM Watson competed against and defeated former champions on the television quiz show Jeopardy! in February 2011.","approach":"The DeepQA system generated candidate answers, gathered and scored evidence, estimated confidence and selected responses.","significance":"It demonstrated the integration of natural-language processing, information retrieval, evidence scoring and large-scale computing.","impact":"Watson became a highly visible example of specialised question-answering technology.","limitations":"Watson was a specialised question-answering system, not a modern large language model or a general-purpose human-equivalent intelligence.","sources":[("IBM Research — Building Watson: An Overview of the DeepQA Project","https://www.aaai.org/Papers/AI Magazine/2010/aimag_vol31_no3.pdf"),("IBM — Watson history","https://www.ibm.com/history/watson-jeopardy") ]},
    {"id":"AI-019","layer":5,"date":"2012","title":"AlexNet","contributors":"Alex Krizhevsky, Ilya Sutskever and Geoffrey Hinton","what":"AlexNet was a deep convolutional neural network that achieved a major result in the 2012 ImageNet Large Scale Visual Recognition Challenge.","approach":"It combined convolutional layers, ReLU activations, pooling, data augmentation, dropout and GPU training.","significance":"Its performance helped establish large-scale deep convolutional learning as a powerful approach to image recognition.","impact":"It accelerated investment and research in deep learning across computer vision and other fields.","limitations":"The reported 15.3% top-5 error was achieved by an ensemble; the single CNN's top-5 error was 18.9%. CNNs predated AlexNet.","sources":[("NeurIPS — original AlexNet paper","https://proceedings.neurips.cc/paper/2012/hash/c399862d3b9d6b76c8436e924a68c45b-Abstract.html"),("Original paper PDF","https://papers.nips.cc/paper/2012/file/c399862d3b9d6b76c8436e924a68c45b-Paper.pdf") ]},
    {"id":"AI-020","layer":5,"date":"2014","title":"Generative Adversarial Networks (GANs)","contributors":"Ian Goodfellow and collaborators","what":"GANs introduced a framework in which a generator and discriminator are trained adversarially.","approach":"The generator creates samples while the discriminator learns to distinguish generated samples from real training examples; both improve through competition.","significance":"The framework created a powerful new approach to generative modelling and realistic synthetic data.","impact":"GANs influenced image synthesis, editing, data augmentation and generative AI research.","limitations":"Training can be unstable and suffer from mode collapse; the original preprint appeared in June 2014 and the work was presented at NeurIPS 2014.","sources":[("NeurIPS 2014 — Generative Adversarial Nets","https://proceedings.neurips.cc/paper/2014/hash/f033ed80deb0234979a61f95710dbe25-Abstract.html"),("Original arXiv preprint","https://arxiv.org/abs/1406.2661") ]},
    {"id":"AI-021","layer":5,"date":"2016","title":"AlphaGo defeats Lee Sedol","contributors":"DeepMind AlphaGo team; Lee Sedol","what":"DeepMind's AlphaGo defeated Go champion Lee Sedol by four games to one in a five-game match in March 2016.","approach":"AlphaGo combined deep neural networks, search and reinforcement learning to evaluate positions and select moves.","significance":"The result demonstrated strong machine performance in Go, a game with an enormous search space.","impact":"It advanced research in learning and planning and became a landmark for AI in strategic games.","limitations":"AlphaGo had already defeated European champion Fan Hui in 2015; the Lee Sedol match was not its first professional-level victory.","sources":[("Nature — Mastering the game of Go with deep neural networks and tree search","https://www.nature.com/articles/nature16961"),("DeepMind — AlphaGo research","https://deepmind.google/research/alphago/") ]},
    {"id":"AI-022","layer":5,"date":"2017","title":"Transformer architecture","contributors":"Ashish Vaswani and colleagues","what":"The Transformer introduced an architecture for sequence transduction based on attention mechanisms rather than recurrence or convolution.","approach":"Self-attention lets a model relate different positions in a sequence, with parallelisable processing and positional information.","significance":"It provided a scalable architecture that became foundational to many modern language and multimodal models.","impact":"Transformers underpin much of the current foundation-model ecosystem.","limitations":"The paper did not invent attention itself; compute and data requirements can be substantial, and attention alone does not guarantee reliable reasoning.","sources":[("NeurIPS — Attention Is All You Need","https://papers.nips.cc/paper/7181-attention-is-all-you-need"),("Original arXiv paper","https://arxiv.org/abs/1706.03762") ]},
    {"id":"AI-023","layer":6,"date":"2020","title":"GPT-3","contributors":"OpenAI research team","what":"GPT-3 was a 175-billion-parameter autoregressive language model that demonstrated strong few-shot performance across a range of language tasks.","approach":"A Transformer language model predicts the next token and can adapt to tasks through examples and instructions in its prompt.","significance":"It brought large-scale few-shot language modelling to wide attention and helped shape the foundation-model era.","impact":"GPT-3 influenced later language-model products, research and prompt-based workflows.","limitations":"Few-shot performance is not the same as robust understanding; the model can produce inaccurate or biased outputs.","sources":[("Original paper — Language Models are Few-Shot Learners","https://arxiv.org/abs/2005.14165"),("OpenAI GPT-3 research announcement","https://openai.com/index/language-models-are-few-shot-learners/") ]},
    {"id":"AI-024","layer":6,"date":"2020–2021","title":"AlphaFold 2","contributors":"DeepMind AlphaFold team","what":"AlphaFold 2 achieved a major advance in predicting three-dimensional protein structures from amino-acid sequences, with results at CASP14 in 2020 and a major Nature paper in 2021.","approach":"A deep-learning system integrated sequence and structural information to predict protein structures with high accuracy.","significance":"It addressed a long-standing scientific challenge and made high-quality structure predictions broadly useful to researchers.","impact":"It accelerated structural biology research and downstream scientific discovery.","limitations":"Predicted structures are not the same as experimental confirmation; some proteins, complexes and dynamic states remain challenging.","sources":[("Nature — Highly accurate protein structure prediction with AlphaFold","https://www.nature.com/articles/s41586-021-03819-2"),("DeepMind — AlphaFold","https://deepmind.google/science/alphafold/") ]},
    {"id":"AI-025","layer":6,"date":"2020–2022","title":"Diffusion models and AI image generation","contributors":"Jonathan Ho, Ajay Jain, Pieter Abbeel and many later research teams","what":"Diffusion research developed into a major approach for generating images and other data, with rapid progress in text-to-image systems by 2022.","approach":"A model learns to reverse a gradual noising process, generating samples by iteratively denoising from noise; text conditioning can guide image generation.","significance":"Diffusion models enabled high-quality controllable image generation and became central to modern generative media.","impact":"They powered influential image-generation systems and expanded creative and design workflows.","limitations":"The original DALL·E (2021) was autoregressive; DALL·E 2 (2022) used diffusion. Generated images can contain errors, bias and copyright-related concerns.","sources":[("NeurIPS 2020 — Denoising Diffusion Probabilistic Models","https://proceedings.neurips.cc/paper/2020/hash/4c5bcfec8584af0d967f1ab10179ca4b-Abstract.html"),("OpenAI — DALL·E 2","https://openai.com/index/dall-e-2/") ]},
    {"id":"AI-026","layer":6,"date":"30 November 2022","title":"ChatGPT public launch","contributors":"OpenAI","what":"OpenAI publicly released ChatGPT as a conversational system based on models from the GPT-3.5 series.","approach":"The system was fine-tuned for dialogue using supervised examples and reinforcement learning from human feedback.","significance":"The public release made conversational generative AI widely accessible and brought large language models into mainstream public discussion.","impact":"It accelerated adoption, experimentation and debate about generative AI in education, work and software.","limitations":"ChatGPT can generate plausible but false information and requires appropriate human verification.","sources":[("OpenAI — Introducing ChatGPT","https://openai.com/index/chatgpt/"),("InstructGPT research paper","https://arxiv.org/abs/2203.02155") ]},
    {"id":"AI-027","layer":6,"date":"2023","title":"Multimodal foundation models","contributors":"OpenAI, Google and the wider AI research community","what":"A new wave of foundation models expanded beyond text-only interaction to process or generate multiple modalities such as images, audio, video and text.","approach":"Large neural models are trained or adapted to represent and connect information across different modalities.","significance":"Multimodality made it possible to build more flexible systems that can interpret and respond to richer real-world inputs.","impact":"It broadened AI applications in accessibility, search, education, content creation and human-computer interaction.","limitations":"Multimodal AI existed before 2023; model capabilities differ, and perception errors, bias and safety issues remain.","sources":[("OpenAI — GPT-4 research","https://openai.com/index/gpt-4-research/"),("Google — Introducing Gemini","https://blog.google/innovation-and-ai/technology/ai/google-gemini-ai/") ]},
    {"id":"AI-028","layer":6,"date":"2024","title":"Reasoning-oriented AI models","contributors":"OpenAI and the wider reasoning-model research community","what":"A prominent new wave of models was designed to spend additional computation on solving difficult multi-step problems before responding.","approach":"Training approaches including reinforcement learning encourage models to develop and use longer problem-solving processes.","significance":"These systems highlighted a distinct direction for improving performance on complex mathematics, coding and structured reasoning tasks.","impact":"They influenced model development, evaluation and expectations about test-time computation.","limitations":"AI reasoning research is much older; modern reasoning models can still make mistakes, and performance varies by task and evaluation method.","sources":[("OpenAI — Introducing OpenAI o1-preview","https://openai.com/index/introducing-openai-o1-preview/"),("OpenAI — Learning to reason with LLMs","https://openai.com/index/learning-to-reason-with-llms/") ]},
    {"id":"AI-029","layer":6,"date":"2025–present","title":"AI agents","contributors":"Research labs, model developers and the broader AI agent ecosystem","what":"Foundation-model-based agents increasingly combine language models with tools, planning, memory and the ability to perform multi-step tasks.","approach":"An agent can interpret a goal, plan steps, call tools or external systems, observe results and revise its actions.","significance":"Agents move AI from producing a single response toward carrying out sequences of actions in digital environments.","impact":"They are being explored for research, software development, administration, customer support and workflow automation.","limitations":"AI agents predate this period; modern agents still face reliability, security, evaluation, oversight and long-horizon task challenges.","sources":[("2025 AI Agent Index","https://aiagentindex.mit.edu/data/2025-AI-Agent-Index.pdf"),("International AI Safety Report 2026","https://internationalaisafetyreport.org/publication/international-ai-safety-report-2026") ]},
]


def validate_data():
    expected = [f"AI-{i:03d}" for i in range(1, 30)]
    ids = [m["id"] for m in MILESTONES]
    assert ids == expected, "Milestone IDs/order must remain AI-001 through AI-029"
    assert len(LAYERS) == 6
    assert all(1 <= m["layer"] <= 6 for m in MILESTONES)
    assert all(m.get("title") and m.get("sources") for m in MILESTONES)
    assert all(url.startswith("https://") for m in MILESTONES for _, url in m["sources"])
    return True
